'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var namedtypedtuple = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof namedtypedtuple, 'function', 'main export is a function' );
	t.end();
});

tape( 'a tuple has an `includes` method', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point();

	t.strictEqual( hasProp( p, 'includes' ), true, 'returns expected value' );
	t.strictEqual( isFunction( p.includes ), true, 'returns expected value' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a tuple instance', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.includes.call( value, 1 );
		};
	}
});

tape( 'the method returns `true` if a tuple includes a search element', function test( t ) {
	var Point;
	var bool;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	bool = p.includes( 1 );
	t.strictEqual( bool, true, 'returns expected value' );

	bool = p.includes( 2 );
	t.strictEqual( bool, true, 'returns expected value' );

	bool = p.includes( 3 );
	t.strictEqual( bool, true, 'returns expected value' );

	t.end();
});

tape( 'the method returns `false` if a tuple does not include a search element', function test( t ) {
	var Point;
	var bool;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	bool = p.includes( 10 );
	t.strictEqual( bool, false, 'returns expected value' );

	t.end();
});

tape( 'the method supports specifying a starting index', function test( t ) {
	var Point;
	var bool;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	bool = p.includes( 1, 1 );
	t.strictEqual( bool, false, 'returns expected value' );

	bool = p.includes( 3, 1 );
	t.strictEqual( bool, true, 'returns expected value' );

	t.end();
});

tape( 'the method supports specifying a negative starting index', function test( t ) {
	var Point;
	var bool;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	bool = p.includes( 1, -2 );
	t.strictEqual( bool, false, 'returns expected value' );

	bool = p.includes( 3, -1 );
	t.strictEqual( bool, true, 'returns expected value' );

	t.end();
});

tape( 'the method does not distinguish between signed and unsigned zero', function test( t ) {
	var Point;
	var bool;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 0.0, 1.0 ] );

	bool = p.includes( -0.0 );
	t.strictEqual( bool, true, 'returns expected value' );

	bool = p.includes( 0.0 );
	t.strictEqual( bool, true, 'returns expected value' );

	t.end();
});

tape( 'the method can find NaN values', function test( t ) {
	var Point;
	var bool;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ NaN, 1 ] );

	bool = p.includes( NaN );
	t.strictEqual( bool, true, 'returns expected value' );

	t.end();
});
